154	            const unsigned rc     = lib.nvlink_state(entry.second, static_cast<unsigned>(link), &active);
155	            if (rc == kNvmlNotSupported || rc == kNvmlInvalidArgument) {
156	                answered = true;  // the device has no more links, which is an answer
157	                break;
158	            }
159	            if (rc != kNvmlSuccess) {
160	                break;  // anything else means we genuinely could not ask
161	            }
162	            answered = true;
163	            if (active == 0) {
164	                continue;
165	            }
166	            unsigned kind = 0;
167	            if (lib.nvlink_remote_type(entry.second, static_cast<unsigned>(link), &kind) != kNvmlSuccess) {
168	                continue;
169	            }
170	            if (kind == kRemoteSwitch) {
171	                on_switch.insert(entry.first);
172	            }
173	            else if (kind == kRemoteGpu) {
174	                NvmlPciInfo info{};
175	                if (lib.nvlink_remote_pci(entry.second, static_cast<unsigned>(link), &info) != kNvmlSuccess) {
