207	Window UlyssesGroup::allocate(int64_t numel, at::ScalarType dtype)
208	{
209	    // Every rank computes the same window size (it is the max over all ranks), so this throws on
210	    // all of them together and cannot leave anyone waiting. A zero-sized symmetric allocation has
211	    // a null data_ptr, which rendezvous refuses with a null handle.
212	    TORCH_CHECK(numel > 0,
213	                "this call moves no data: every rank's shard is empty. Check the shape and the "
214	                "splits -- a sequence or head axis of 0 on ALL ranks has nothing to exchange");
215	    const at::cuda::CUDAGuard guard(device_index_);
216	    // empty_strided_p2p rather than a MemPool: it is the allocator entry point directly, so no
217	    // unrelated allocation can interleave with ours and desync the rendezvous order across ranks.
218	    at::Tensor t = symm::empty_strided_p2p(
219	        {numel}, {1}, dtype, c10::Device(c10::DeviceType::CUDA, device_index_), group_name_, std::nullopt);
220	    auto sym = symm::rendezvous(t, group_name_);

