39	// Validation and dims for the 4D a2a. Everything checked here is part of the plan cache key, so a
40	// cache hit cannot skip a check that would have failed: the same values already passed it. Checks
41	// that depend on the tensor rather than its shape (device, contiguity, aliasing) stay per-call.
42	//
43	// The plan treats uneven as the general case, so the only decision here is what the splits ARE:
44	// the caller's, or the even ones the shape implies.
45	A2ADims make_dims(at::IntArrayRef                            sizes,
46	                  at::ScalarType                             dtype,
47	                  int64_t                                    mode,
48	                  int                                        ws,
49	                  int                                        rank,
50	                  const std::optional<std::vector<int64_t>>& seq_splits,
51	                  const std::optional<std::vector<int64_t>>& head_splits)
52	{
53	    TORCH_CHECK(sizes.size() == 4, "input must be 4D, got ", sizes.size(), " dims");
54	    // Listed, not opened up. Nothing below this line is dtype-specific -- build_plan takes an
55	    // elem_size, the transport copies bytes, the window map and the plan key both carry the dtype,
56	    // and empty_strided_p2p takes a plain ScalarType -- so the set is a decision, not a constraint.
57	    // Leaving the check off entirely would admit kBool, the complex types and the quantized ones,
58	    // which nothing here has reasoned about.
59	    TORCH_CHECK(dtype == at::kHalf || dtype == at::kBFloat16 || dtype == at::kFloat || dtype == at::kFloat8_e4m3fn
60	                    || dtype == at::kFloat8_e5m2 || dtype == at::kChar || dtype == at::kByte,
61	                "dtype must be float16, bfloat16, float32, float8_e4m3fn, float8_e5m2, int8 or uint8, got ",
62	                dtype);
63	    const int64_t x1   = sizes[1];
64	    const int64_t x2   = sizes[2];
65	    const int64_t d    = sizes[3];
66	    const int64_t elem = static_cast<int64_t>(c10::elementSize(dtype));
67	    // One check covers the whole plan: every byte quantity build_plan emits -- src_offset,
68	    // dst_offset, width, both pitches, the batch strides -- is a multiple of d * elem. Note the
69	    // rule TIGHTENS as the element shrinks: d % 8 at fp16, d % 4 at fp32, d % 16 at fp8 and int8.
70	    TORCH_CHECK(
71	        (d * elem) % 16 == 0, "the head dim must be 16-byte aligned: d=", d, " x ", elem, " B is ", d * elem, " B");
72	    TORCH_CHECK(mode == 0 || mode == 1, "mode must be 0 or 1, got ", mode);
73	
74	    A2ADims dims;
75	    dims.b          = sizes[0];
76	    dims.d          = d;
77	    dims.rank       = rank;
78	    dims.world_size = ws;
79	
80	    if (seq_splits.has_value() || head_splits.has_value()) {
81	        // One without the other has no meaning: the plan needs the WHOLE group's geometry, and the
82	        // missing half cannot be inferred from a shape that is itself already sharded.
83	        TORCH_CHECK(seq_splits.has_value() && head_splits.has_value(),
84	                    "pass both seq_splits and head_splits, or neither");
85	        dims.seq_splits  = *seq_splits;
86	        dims.head_splits = *head_splits;
87	        dims.validate();  // length and sign, before indexing by rank below
88	        // Cross-check against the tensor handed in, so a caller that mis-shards gets an error here
89	        // instead of a silently corrupt result.
90	        const int64_t expect_x1 = (mode == 0) ? dims.seq_splits[rank] : dims.seq_total();
91	        const int64_t expect_x2 = (mode == 0) ? dims.head_total() : dims.head_splits[rank];
92	        TORCH_CHECK(x1 == expect_x1 && x2 == expect_x2,
93	                    "input is [",
94	                    dims.b,
95	                    ", ",
96	                    x1,
97	                    ", ",
98	                    x2,
99	                    ", ",
100	                    d,
101	                    "] but the splits imply [",
102	                    dims.b,
103	                    ", ",
104	                    expect_x1,
105	                    ", ",
106	                    expect_x2,
107	                    ", ",
108	                    d,
109	                    "]");
110	        return dims;
111	    }
112	
113	    // No splits: the even special case, which the shape alone determines only if the scattered
114	    // axis divides. The other axis is already sharded on entry, so it never has to.
115	    if (mode == 0) {
116	        TORCH_CHECK(x2 % ws == 0,
117	                    "mode 0 scatters the head axis, so n_global (",
118	                    x2,
119	                    ") must divide world_size (",
120	                    ws,
121	                    ") -- or pass seq_splits and head_splits");
122	        dims.seq_splits.assign(ws, x1);
123	        dims.head_splits.assign(ws, x2 / ws);
124	    }
125	    else {
126	        TORCH_CHECK(x1 % ws == 0,
127	                    "mode 1 scatters the sequence axis, so s_global (",
128	                    x1,
129	                    ") must divide world_size (",
130	                    ws,
131	                    ") -- or pass seq_splits and head_splits");
132	        dims.seq_splits.assign(ws, x1 / ws);
133	        dims.head_splits.assign(ws, x2);
134	    }
135	    return dims;
136	}
