304	at::Tensor UlyssesGroup::make_output(at::IntArrayRef shape, at::ScalarType dtype, int64_t numel)
305	{
306	    check_alive();
307	    prune_owned();  // before allocating, so a released buffer's memory can be reused right here
308	    Window     win = allocate(numel, dtype);
309	    at::Tensor out = win.tensor.narrow(0, 0, c10::multiply_integers(shape)).view(shape);
310	    owned_.emplace(win.tensor.data_ptr(), std::move(win));
311	    return out;
312	}
